def r(x):
    x = float(x)
    t = 6.0 * x - 3.0
    t_perturbed = t + 0.5 * (3.0 - t)  # Move t toward upper asymptote (3.0), so x toward 1.0
    x_perturbed = (t_perturbed + 3.0) / 6.0
    return max(min(x_perturbed, 1.0), 0.0)


